const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { chromium } = require('C:/Users/GDesktop-1/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async () => {
  const task = __dirname;
  const browser = await chromium.launch({channel:'msedge',headless:true});
  const images=[];
  try {
    const names = fs.readdirSync(task).filter(n => /^final-fix-(?:settings|cleanup)-.*\.svg$/.test(n));
    for(const name of names) {
      const svg=path.join(task,name), png=svg.replace(/\.svg$/,'.png');
      const source=fs.readFileSync(svg,'utf8');
      const [,width,height]=source.match(/viewBox="0 0 ([\d.]+) ([\d.]+)"/);
      const page=await browser.newPage({viewport:{width:Math.ceil(+width),height:Math.ceil(+height)},deviceScaleFactor:1});
      await page.route(/^https?:/,route=>route.abort());
      await page.setContent(`<html><body style="margin:0"><img width="${Math.ceil(+width)}" height="${Math.ceil(+height)}" src="data:image/svg+xml;base64,${Buffer.from(source).toString('base64')}"></body></html>`);
      await page.evaluate(()=>document.fonts.ready);
      await page.screenshot({path:png,fullPage:false,timeout:15000});
      await page.close();
      const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
      images.push({svg,svg_sha256:hash(svg),png,png_sha256:hash(png),source_qualification:'Final source mounted Settings and cleanup action; see final-fix-covering.txt and source manifest'});
    }
  } finally { await browser.close(); }
  fs.writeFileSync(path.join(task,'final-fix-mounted-render.json'),JSON.stringify({rendered_utc:new Date().toISOString(),renderer:'Existing Playwright + installed Edge; HTTP(S) aborted; local SVG only',mounted_evidence:'Final focused covering includes mounted full Settings/card/control focus and stable post-startup theme assertions. Clear frames show action focus; cleanup frames show actual result.',images},null,2));
  console.log(JSON.stringify({rendered:images.length}));
})();

